// WORKER_NAME; o dele declara "axion-api-cg". Fora da casa, sem chave salva, a porta fica fechada
// e a tela pede pra gerar uma.
const _ehDashDaCasa = (env) => !env || !env.WORKER_NAME || String(env.WORKER_NAME) === 'axion-api';
const _INTEG_SEGREDOS = {
  payt_token:     { env: 'PAYT_TOKEN', padrao: (env) => (_ehDashDaCasa(env) ? PAYT_TOKEN_DEFAULT : '') },
  five_token:     { env: 'FIVE_TOKEN', padrao: (env) => (_ehDashDaCasa(env) ? FIVE_TOKEN_DEFAULT : '') },
  pl_token:       { env: 'PAYLOG_TOKEN' },
  // env2 (14/10/2026): o segredo do Webhooks v2 da PayLog normal tambem vale (ver _plSegredoOk). Sem ele a
  // tela dizia "falta o segredo" numa dash que so tem a PayLog normal e o segredo no secret do servidor.
  pl_secret:      { env: 'PAYLOG_SECRET', env2: 'PAYLOG2_SECRET' },
  dc_api_key:     {},
  dc_hook_secret: {},
  // APP SECRET DO APP DA META (09/10/2026, item 34): assina o POST /api/wa/cloud. Secret do worker
  // ou salvo pela tela de Integracoes; so da casa (a porta e uma so, do app 234648803045985).
  wa_api_app_secret: { env: 'WA_APP_SECRET' },
};
// ══ CADA MUNDO TEM AS PROPRIAS CHAVES ═════════════════════════════════════
//
// 11/09/2026, pedido do Bruno: "quero disponibilizar pros meus afiliados a conexao do Datacrazy e
// da PayLog, pra eles atenderem pelo mesmo inbox que a gente usa".
//
// Ate aqui o app_config tinha UMA linha por chave: `dc_api_key` era a do Bruno e acabou. Com o
// afiliado configurando pela tela, a PRIMEIRA coisa que aconteceria e ele salvar a chave do
// Datacrazy dele por cima da nossa - e o inbox da casa inteiro pararia de sincronizar sem erro
// nenhum aparecer, porque chave errada e chave ausente se parecem muito.
//
// Entao a chave ganha o dono no proprio nome: `dc_api_key` continua sendo a da casa e
// `dc_api_key__afl_3d767329` e a daquele afiliado. Chave sem sufixo fica exatamente onde estava,
// entao nada do que ja roda muda de lugar - a migracao e nao fazer nada.
const _cfgNome = (chave, mundo) => (mundo ? chave + '__' + mundo : chave);

// Devolve o valor E DE ONDE ele veio. A procedencia importa na tela: "salva na dash" e "secret do
// servidor" se comportam igual pro worker e MUITO diferente pra quem precisa trocar.
async function _integChave(env, chave, mundo) {
  const def = _INTEG_SEGREDOS[chave] || {};
  const naDash = await _readConfig(env, _cfgNome(chave, mundo));
  if (naDash) return { valor: String(naDash), fonte: 'dash' };
  // O MUNDO DO AFILIADO NAO HERDA A CHAVE DA CASA, e isso e o ponto mais importante deste bloco.
  // O secret do worker e a constante deste arquivo sao NOSSOS: se o mundo dele caisse neles, o
  // pedido dele entraria pela nossa conta da PayLog e a conversa do cliente dele apareceria no
  // nosso Datacrazy. Sem chave propria a conexao dele esta DESLIGADA - que e a verdade, e e o que
  // a tela precisa dizer pra ele ir configurar.
  if (mundo) return { valor: '', fonte: '' };
  const noEnv = def.env && env ? (env[def.env] || (def.env2 ? env[def.env2] : '')) : '';
  if (noEnv) return { valor: String(noEnv), fonte: 'servidor' };
  const pad = def.padrao ? def.padrao(env) : '';
  if (pad) return { valor: String(pad), fonte: 'padrao' };
  return { valor: '', fonte: '' };
}

// DE QUEM E ESTE SEGREDO? Devolve '' pra casa, o id do afiliado pro mundo dele, e null quando o
// segredo nao bate com ninguem.
//
// E assim que o webhook do Datacrazy sabe em qual mundo entregar: a URL de cada um leva o segredo
// dele, entao o proprio segredo e a identidade. Sem isto, ou todo mundo compartilha um segredo (e
// ai qualquer um posta no mundo do outro), ou seria preciso inventar um parametro a mais na URL -
// que a pessoa pode errar ao colar, e o segredo nao.
async function _mundoPorSegredo(env, chave, valor) {
  const v = String(valor || '');
  if (!v) return null;
  await _ensureConfigTable(env);
  try {
    const r = await env.DB.prepare('SELECT key, value FROM app_config WHERE key = ? OR key LIKE ?')
      .bind(chave, chave + '__%').all();
    for (const row of (r.results || [])) {
      if (String(row.value || '') !== v) continue;
      const k = String(row.key || '');
      return k === chave ? '' : k.slice(chave.length + 2);
    }
  } catch (_) {}
  return null;
}

// Os mundos que TEM uma chave dessas configurada, pra varredura do cron saber por quem passar.
// Sempre inclui a casa ('') quando ela tem a chave; os afiliados entram pelo sufixo.
async function _mundosCom(env, chave) {
  const saida = [];
  await _ensureConfigTable(env);
  try {
    const r = await env.DB.prepare("SELECT key FROM app_config WHERE (key = ? OR key LIKE ?) AND COALESCE(value,'') <> ''")
      .bind(chave, chave + '__%').all();
    for (const row of (r.results || [])) {
      const k = String(row.key || '');
      saida.push(k === chave ? '' : k.slice(chave.length + 2));
    }
  } catch (_) {}
  return saida;
}

// JANELA DE TROCA DE CHAVE (7 dias).
//
// Sem ela, esta tela seria uma armadilha: a pessoa gera a chave nova, clica em salvar, e a URL
// antiga - que e a que esta cadastrada la na Payt/Five - morre no mesmo segundo. Todo webhook
// entre o salvar e o colar volta 401, e o pedido desse intervalo simplesmente nao existe pra dash.
// E pior: 401 nao aparece em tela nenhuma, so no log cru.
//
// Entao a chave ANTERIOR continua valendo por uma semana. Tempo de sobra pra trocar no painel da
// plataforma sem perder nada, e curto o bastante pra uma chave vazada nao ficar viva pra sempre.
async function _integTokenOk(env, chave, recebido) {
  const r = String(recebido || '');
  if (!r) return false;
  const atual = await _integChave(env, chave);
  if (atual.valor && r === atual.valor) return true;
  const ant = await _readConfig(env, chave + '_ant');
  if (!ant) return false;
  const corte = String(ant).lastIndexOf('|');
  if (corte < 1) return false;
  const valor = String(ant).slice(0, corte);
  const quando = Number(String(ant).slice(corte + 1)) || 0;
  if (valor !== r) return false;
  return (Math.floor(Date.now() / 1000) - quando) < 7 * 86400;
}

// ─── Helpers ───
const json = (data, status = 200) => new Response(JSON.stringify(data), {
  status,
  headers: {
    'content-type': 'application/json; charset=utf-8',
    'access-control-allow-origin': '*',
    'access-control-allow-headers': 'authorization, content-type',
    'access-control-allow-methods': 'GET, POST, DELETE, OPTIONS',
    'access-control-max-age': '86400',
    'cache-control': 'no-store',
  },
});

const err = (msg, status = 400) => json({ error: msg }, status);

// SENHA COM SAL (09/10/2026, auditoria item 36). Ate aqui a senha era sha256 puro do texto: duas
// pessoas com a mesma senha tinham o mesmo hash, e um vazamento da tabela users dava pra quebrar
// por tabela pronta. Agora: PBKDF2-SHA256, 100 mil iteracoes, sal de 16 bytes, no formato
// `pbkdf2$<iter>$<sal hex>$<hash hex>`. O hash ANTIGO (64 hex) continua entrando: confereSenha
// reconhece os dois, e o login bem-sucedido com hash antigo regrava no formato novo (migracao
// transparente, sem ninguem precisar trocar de senha). O banco do Giovane roda este mesmo codigo.
const _PBKDF2_ITER = 100000;
const _hex = (buf) => Array.from(new Uint8Array(buf)).map((x) => x.toString(16).padStart(2, '0')).join('');
async function _pbkdf2Hex(senha, salHex, iter) {
  const sal = new Uint8Array(salHex.match(/.{2}/g).map((h) => parseInt(h, 16)));
  const chave = await crypto.subtle.importKey('raw', new TextEncoder().encode(String(senha)), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt: sal, iterations: iter }, chave, 256);
  return _hex(bits);
}
async function hashSenha(senha) {
  const salHex = _hex(crypto.getRandomValues(new Uint8Array(16)));
  return 'pbkdf2$' + _PBKDF2_ITER + '$' + salHex + '$' + (await _pbkdf2Hex(senha, salHex, _PBKDF2_ITER));
}
// Devolve { ok, legado }: legado = true quando conferiu pelo sha256 antigo (hora de regravar).
async function confereSenha(senha, guardado) {
  const g = String(guardado || '');
  if (!g) return { ok: false, legado: false };
  if (g.startsWith('pbkdf2$')) {
    const [, iter, salHex, hash] = g.split('$');
    const calc = await _pbkdf2Hex(senha, salHex, Number(iter) || _PBKDF2_ITER);
    return { ok: _iguaisConstante(calc, hash), legado: false };
  }
  if (/^[a-f0-9]{64}$/i.test(g)) {
    const calc = await sha256Hex(senha);
    return { ok: _iguaisConstante(calc, g.toLowerCase()), legado: true };
  }
  return { ok: false, legado: false };
}
function _iguaisConstante(a, b) {
  const x = String(a), y = String(b);
  if (x.length !== y.length) return false;
  let d = 0;
  for (let i = 0; i < x.length; i++) d |= x.charCodeAt(i) ^ y.charCodeAt(i);
  return d === 0;
}

// LIMITE DE TENTATIVAS DE LOGIN (09/10/2026, item 36). Sem binding novo no wrangler.toml (decisao do
// ADENDO): contador em memoria do isolate, por login e por IP, 10 tentativas por 60 s, com teto de
// chaves pra nunca crescer sem fim. E por isolate, entao nao e absoluto - mas transforma "milhares
// de tentativas por minuto" em "dez por isolate por minuto", e cada falha fica no log. Zero escrita
// no D1 (uma falha de login virar um write era o que a auditoria proibiu).
const _loginTent = new Map();
const _LOGIN_MAX = 10, _LOGIN_JANELA_MS = 60000;
function _loginEstourou(chave) {
  const agora = Date.now();
  if (_loginTent.size > 500) _loginTent.clear();
  const lista = (_loginTent.get(chave) || []).filter((t) => agora - t < _LOGIN_JANELA_MS);
  _loginTent.set(chave, lista);
  return lista.length >= _LOGIN_MAX;
}
function _loginFalhou(chave) {
  const lista = _loginTent.get(chave) || [];
  lista.push(Date.now());
  _loginTent.set(chave, lista);
}

async function sha256Hex(text) {
  // (sem sal: so pro hash LEGADO da senha e pros hashes do pixel; senha nova usa hashSenha)
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
  return [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join('');
}

function randomToken() {
  const arr = new Uint8Array(32);
  crypto.getRandomValues(arr);
  return [...arr].map(b => b.toString(16).padStart(2, '0')).join('');
}

async function authUser(req, env) {
  const u = await _authSessao(req, env);
  return u ? _verComoNaLeitura(req, env, u) : null;
}
// VER COMO OUTRA PESSOA VALE PRA TODA LEITURA (15/09/2026, pedido do Bruno: "quando eu clicar no meu
// cobrador, quero ver exatamente o que ele ve quando faz login"). Antes o `como` so era lido por umas
// oito rotas (estado, inbox, pedidos, conexoes...); todas as outras respondiam como o DIRETOR, e cada
// tela nova nascia mostrando no preview uma coisa que a pessoa nao ve. Agora e aqui, na autenticacao:
// um GET com ?como=<id> vindo de diretor responde como aquela pessoa, com as MESMAS colunas que o login
// dela traz (ve_desde e afiliado_id inclusive, que mudam o recorte).
// As regras de antes continuam: so ESTREITA (o alvo nunca e diretor, entao nao ha como ver mais), so
// LEITURA (gravacao segue como o diretor; o POST /api/state recusa o carimbo __como), e `_comoDe`
// marca que a resposta e de preview.
async function _verComoNaLeitura(req, env, u) {
  const metodo = String(req.method || 'GET').toUpperCase();
  if ((metodo !== 'GET' && metodo !== 'HEAD') || !isDirector(u)) return u;
  let como = '';
  try { como = new URL(req.url).searchParams.get('como') || ''; } catch (_) { como = ''; }
  if (!como || String(como) === String(u.id)) return u;
  const SEL = (extra) => 'SELECT id, login, name, abbr, role, color, bg, com_pct, photo, banner, email' + extra + ' FROM users WHERE id = ? AND COALESCE(archived,0) = 0';
  let alvo = null;
  try { alvo = await env.DB.prepare(SEL(', afiliado_id, ve_desde')).bind(String(como)).first(); }
  catch (_) {
    try { alvo = await env.DB.prepare(SEL(', afiliado_id')).bind(String(como)).first(); }
    catch (_2) { try { alvo = await env.DB.prepare(SEL('')).bind(String(como)).first(); } catch (_3) { alvo = null; } }
  }
  if (!alvo || isDirector(alvo)) return u;
  return { ...alvo, user_id: alvo.id, expires_at: u.expires_at, _comoDe: String(u.id) };
}
// SESSAO LEMBRADA POR 10s, SO PRA LEITURA (19/09/2026, o inbox tem que ser rapido). Achar a
// sessao e uma ida ao D1 (~200ms) em TODA requisicao, e o inbox de cada vendedor faz quatro
// leituras a cada poucos segundos - era o maior custo fixo que sobrou depois da assinatura.
// So GET/HEAD usa a memoria: gravacao vai ao banco sempre. O pior caso e uma sessao apagada
// (logout, troca de senha) ainda conseguir LER por ate 10s - nunca escrever. Por isolate, entao
// deploy novo zera tudo; expiracao da sessao continua valendo (o prazo e conferido na leitura).
const _sessaoCache = new Map();   // token -> { row, t }
const _SESSAO_CACHE_MS = 10000;
async function _authSessao(req, env) {
  const auth = req.headers.get('authorization') || '';
  const m = auth.match(/^Bearer\s+([a-f0-9]{64})$/i);
  if (!m) return null;
  const token = m[1];
  const now = Math.floor(Date.now() / 1000);
  const _leitura = req.method === 'GET' || req.method === 'HEAD';
  if (_leitura) {
    const c = _sessaoCache.get(token);
    if (c && (Date.now() - c.t) < _SESSAO_CACHE_MS && c.row && c.row.expires_at > now) return { ...c.row };
  }
  const _row = await _authSessaoBanco(req, env, token, now);
  if (_leitura && _row) {
    if (_sessaoCache.size > 500) _sessaoCache.clear();   // teto: nunca cresce sem fim
    _sessaoCache.set(token, { row: _row, t: Date.now() });
  }
  return _row;
}
async function _authSessaoBanco(req, env, token, now) {
  // A COLUNA afiliado_id PODE NAO EXISTIR AINDA. Este SELECT roda em TODA requisicao e ANTES de
  // qualquer ALTER TABLE do worker - entao, num banco que ainda nao tem a coluna, ele derruba a API
  // INTEIRA com "no such column" (aconteceu em 23/08/2026: /api/state e /api/wa/chats caindo em
  // 1101 ate a coluna ser criada na mao). O mesmo valeria pro banco do Giovane, que roda este
  // codigo com D1 proprio. Por isso: tenta o SELECT completo, e se a coluna faltar, cria e refaz.
  // Nunca deixe este caminho depender de uma coluna nova sem esta rede.
  let row;
  const SEL = (extra) => `SELECT s.expires_at, s.user_id, u.id, u.login, u.name, u.abbr, u.role, u.color, u.bg, u.com_pct,
            u.photo, u.banner, u.email${extra}
     FROM sessions s JOIN users u ON s.user_id = u.id
     WHERE s.token = ? AND s.expires_at > ?`;
  // ve_desde entra pela MESMA rede acima: o banco do Giovane roda este codigo e pode nao ter a
  // coluna. Cada degrau abaixo perde uma coluna e nunca a autenticacao.
  try {
    row = await env.DB.prepare(SEL(', u.afiliado_id, u.ve_desde')).bind(token, now).first();
  } catch (_) {
    try { await env.DB.prepare('ALTER TABLE users ADD COLUMN afiliado_id TEXT').run(); } catch (_2) {}
    try { await env.DB.prepare('ALTER TABLE users ADD COLUMN ve_desde INTEGER').run(); } catch (_2b) {}
    try { row = await env.DB.prepare(SEL(', u.afiliado_id, u.ve_desde')).bind(token, now).first(); }
    catch (_3) {
      try { row = await env.DB.prepare(SEL(', u.afiliado_id')).bind(token, now).first(); }
      catch (_4) { row = await env.DB.prepare(SEL('')).bind(token, now).first(); }
    }
  }
  if (!row) return null;
  // Sliding expiry: enquanto o usuário usa, renova o prazo. Pra não gravar a cada
  // request (polling de 10s), só renova quando falta menos de (TTL - 1 dia) →
  // no máximo ~1 write/dia por sessão. Assim sessão ativa nunca expira.
  const fullTtl = SESSION_TTL_HOURS * 3600;
  if (row.expires_at - now < fullTtl - 86400) {
    try {
      await env.DB.prepare('UPDATE sessions SET expires_at = ? WHERE token = ?')
        .bind(now + fullTtl, token).run();
    } catch (_) { /* renovação é best-effort */ }
  }
  return row;
}

// O valor pago so pode DESCER em relacao ao pedido: e desconto, nao remarcacao. Sem este teto, um
