    // e na PayLog agora (aprovado, esperando envio). Sem isto o card ficaria um passo na frente do
    // pedido, e a escada da coluna (so sobe) nao deixaria o evento "aprovado" traze-lo de volta.
    if (String(lead.col || '') === 'Enviado' && !lead.ship && !lead.track) {
      lead.hist = Array.isArray(lead.hist) ? lead.hist : [];
      lead.hist.push({ from: 'Enviado', to: 'A Enviar', who: String(u.id), time: new Date().toISOString(), note: 'volta pra A Enviar: o pedido acabou de ser criado na PayLog e ainda nao saiu' });
      lead.col = 'A Enviar';
      if (lead.col_plat === 'Enviado') delete lead.col_plat;
    }
