  const _mDc = (noMundoAfiliado(u) || afiliadoSemVinculo(u)) ? String(aflDe(u) || '\u0000') : '';
  const r = await env.DB.prepare("SELECT id, received_at, ok, phone, self, direction, event, text, raw FROM dc_events WHERE COALESCE(afl,'')=? ORDER BY id DESC LIMIT 30").bind(_mDc).all();
  return json({ events: (r && r.results) || [] });
