  // "WhatsApp oficial sem sincronizar" por causa da NOSSA conta, ou um verde falso sobre a dele.
  const _mundoInbox = (noMundoAfiliado(u) || afiliadoSemVinculo(u)) ? String(aflDe(u) || '') : '';
