  const agoraS = Math.floor(Date.now() / 1000);
  const desde = agoraS - horas * 3600;
  // CARENCIA. Medido em 18/09/2026: o time cadastra o pedido de 5 a 10 minutos depois de mandar o
  // "Pedido Concluido" no WhatsApp. Sem esta folga o aviso piscava em TODA venda e virava ruido - o
  // contrario do que ele pediu ("quero a informacao, mas discreto").
  const ate = agoraS - 30 * 60;
