  const d8 = (v) => { const d = String(v == null ? '' : v).replace(/\D/g, ''); return d.length >= 8 ? d.slice(-8) : ''; };
  const cadastrados = new Set(leads.map((l) => d8(l && l.wa)).filter(Boolean));
  // CASA TAMBEM PELO CPF (18/09/2026). O pedido nem sempre e cadastrado com o telefone da conversa -
  // as vezes entra o contato de quem recebe. O CPF vem na propria mensagem de "Pedido Concluido",
  // entao ele e a chave mais forte que existe aqui. Sem isso o aviso acusava pedido que ESTAVA
  // cadastrado (foi o que o Bruno viu: "todos os pedidos de hoje foram cadastrados").
  const soCpf = (v) => String(v == null ? '' : v).replace(/\D/g, '');
