          if (cl2 && (cl2.ttclid || cl2.pid)) { cliqueNk = String(cl2.num_key || ''); ttclid = cl2.ttclid || ''; pid = cl2.pid || ''; src = 'code'; utm = cl2.utm || ''; fbc = cl2.fbc || ''; fbp = cl2.fbp || ''; visIp = cl2.ip || ''; visUa = cl2.ua || ''; visUrl = cl2.url || ''; visTtp = cl2.ttp || ''; }
