    // mesmo quando o lead não traz o código no texto.
    let nk = String(selfNum || '').replace(/\D/g, '').slice(-8);
    if (!nk) { const _mnk = String(instance || '').match(/_(\d{8})$/); if (_mnk) nk = _mnk[1]; }
    if (!isUpgrade && !pid && nk) {
      try {
        const fb = await env.DB.prepare("UPDATE tt_pending SET claimed=1 WHERE id=(SELECT id FROM tt_pending WHERE num_key=? AND (claimed IS NULL OR claimed=0) AND ts > strftime('%s','now')-3600 ORDER BY (ttclid IS NOT NULL AND ttclid<>'') DESC, ts ASC LIMIT 1) RETURNING ttclid, pid, ip, ua, url, ttp, utm, fbc, fbp, num_key").bind(nk).first();
        if (fb) { cliqueNk = String(fb.num_key || ''); ttclid = fb.ttclid || ''; pid = fb.pid || ''; src = 'fifo'; visIp = fb.ip || ''; visUa = fb.ua || ''; visUrl = fb.url || ''; visTtp = fb.ttp || ''; utm = fb.utm || ''; fbc = fb.fbc || ''; fbp = fb.fbp || ''; }
      } catch (_) {}
    }
    // fallback: linhas antigas, gravadas antes do num_key existir
    if (!isUpgrade && !pid) {
      try {
        const fb = await env.DB.prepare("UPDATE tt_pending SET claimed=1 WHERE id=(SELECT id FROM tt_pending WHERE inst=? AND (claimed IS NULL OR claimed=0) AND ts > strftime('%s','now')-3600 ORDER BY (ttclid IS NOT NULL AND ttclid<>'') DESC, ts ASC LIMIT 1) RETURNING ttclid, pid, ip, ua, url, ttp, utm, fbc, fbp, num_key").bind(instance).first();
        if (fb) { cliqueNk = String(fb.num_key || ''); ttclid = fb.ttclid || ''; pid = fb.pid || ''; src = 'fifo'; visIp = fb.ip || ''; visUa = fb.ua || ''; visUrl = fb.url || ''; visTtp = fb.ttp || ''; utm = fb.utm || ''; fbc = fb.fbc || ''; fbp = fb.fbp || ''; }
      } catch (_) {}
    }
