  let _mundoPag = '';   // '' = a casa (inclusive sem sessao, que e o gestor de trafego da casa)
  try {
    const _up = await authUser(req, env);
    if (_up) {
      _idsPag = _presselIdsVisiveis(_up, data);
      if (noMundoAfiliado(_up) || afiliadoSemVinculo(_up)) _mundoPag = String(aflDe(_up) || '\u0000');
    }
  } catch (_) { /* sem sessao: pagina publica normal, da casa */ }
  // RECORTE POR OPERACAO, dos dois lados (12/09/2026).
  //
  // Aqui tinha um byte NULO no lugar do dono e a comparacao estava invertida (!==): com sessao de
  // afiliado o filtro dos chips nao tirava NADA, e a tabela por vendedor mostrava os NOSSOS numeros
  // pra ele. A varredura pegou com o 91215713 aparecendo pro token do Giovane.
  //
  // E o outro lado: sem sessao (o gestor de trafego da casa) ou com sessao da casa a pagina somava a
  // pressel e os chips do AFILIADO junto dos nossos. Pedido do Bruno: o que e deles fica na area
  // deles. A regra agora e a mesma do .json: cada um ve a propria operacao.
  const pressels=(Array.isArray(data.pressels)?data.pressels:[]).filter(p=>p&&String(p.afl||'')===_mundoPag&&(!_idsPag||_idsPag.has(String(p.id))));
  const chips=(Array.isArray(data.chips)?data.chips:[]).filter(c=>c&&String(c.afl||'')===_mundoPag);
  let day=new URL(req.url).searchParams.get('day')||'';
  if(!/^\d{4}-\d{2}-\d{2}$/.test(day)) day=_brDay();
  else { const _dp=day.split('-'); if(+_dp[1]<1||+_dp[1]>12||+_dp[2]<1||+_dp[2]>31) day=_brDay(); }   // rejeita mês/dia impossível (ex: 2026-00-01)
  const today=_brDay(); if(day>today) day=today;   // seletor de data (não deixa escolher o futuro)
  const isToday=(day===today);
  const _vq=new URL(req.url).searchParams.get('view')||''; let view=(_vq==='vendas'||_vq==='leads')?_vq:'metricas';   // alterna Métricas / Pedidos / Leads
  // Modo completo (números de lead sem máscara + clicáveis + copiar): SÓ com sessão válida (token da dash via ?k=).
  // Sem token → página pública mostra só o final do número (protege os leads, que são o ativo da empresa).
  const kParam=new URL(req.url).searchParams.get('k')||'';
  let full=false;
  // Só libera modo completo pra DIRETOR/SÓCIO ativo (não arquivado). Leads é só-diretor; vendedor não pode
