  const _colNomePag={}; try{ (Array.isArray(data.contCols)?data.contCols:[]).forEach(c=>{ if(c&&c.id) _colNomePag[String(c.id)]=String(c.nome||c.name||c.id); }); }catch(_){}
  const _temNomes=Object.keys(nameMap).length>0;
  const _linhaOk=(x)=>{ const at=String((x&&x.at)||''); if(!at) return false; if(/^ccol_/i.test(at)) return !!full; if(_temNomes && !nameMap[at]) return false; if(_temNomes && String(_aflDeAtPag[at]||'')!==String(_mundoPag||'')) return false; return true; };
  const _maskNum=(n)=>{ const p=String(n||'').replace(/\D/g,''); return p?('…'+p.slice(-4)):'—'; };
