  const _jsDev = `if(_dev){var _pn=document.createElement('div');_pn.style.cssText='position:fixed;left:12px;bottom:12px;z-index:99999;display:flex;flex-direction:column;gap:8px;font:600 13px system-ui,Arial,sans-serif';_pn.onclick=function(e){e.stopPropagation()};var _t=document.createElement('div');_t.textContent='Disparo manual (dev)';_t.style.cssText='background:#05070c;color:#94a3b8;border-radius:9px;padding:5px 9px;font-size:11px;font-weight:600';_pn.appendChild(_t);var _mk=function(rot,fn){var b=document.createElement('button');b.textContent=rot;b.style.cssText='background:#24c278;color:#05070c;border:0;border-radius:11px;padding:11px 14px;font:inherit;cursor:pointer;text-align:left;box-shadow:0 3px 0 rgba(0,0,0,.22)';b.onclick=function(e){e.stopPropagation();var ok=true;try{fn()}catch(_e){ok=false}b.textContent=ok?(rot+' - enviado'):(rot+' - falhou');b.style.background=ok?'#0f766e':'#b91c1c';b.style.color='#fff';setTimeout(function(){b.textContent=rot;b.style.background='#24c278';b.style.color='#05070c'},2600)};_pn.appendChild(b)};_mk('Disparar InitiateCheckout',function(){ttq.track('InitiateCheckout',${_cont})});_mk('Disparar CompletePayment',function(){ttq.track('CompletePayment',${_contPago})});document.body.appendChild(_pn);}`;
