    // CONDICIONALMENTE, senao uma rodada velha apaga a trava da nova.
    try {
      const _agoraS = Date.now();
      const _meuS = String(_agoraS + 90000);
      const _velhoS = Number(await _readConfig(env, 'dc_sync_lock')) || 0;
      if (_agoraS > _velhoS) {
        await _writeConfig(env, 'dc_sync_lock', _meuS);
        try {
          const _rs = await _dcSyncInbox(env, 40, 40, '', 15000);
          if (_rs && _rs.ok !== false && ((_rs.mensagens || 0) > 0)) console.log('DC_SYNC_PRE_TRAVA conversas=' + (_rs.conversas || 0) + ' mensagens=' + (_rs.mensagens || 0));
        } finally {
          const _atual = String(await _readConfig(env, 'dc_sync_lock') || '');
          if (_atual === _meuS) { try { await _writeConfig(env, 'dc_sync_lock', '0'); } catch (_) {} }
        }
      }
    } catch (e) { console.error('[dc-sync] pre-trava falhou: ' + String((e && e.message) || e)); }
    // ══ O INBOX DO AFILIADO TAMBEM SINCRONIZA ANTES DA TRAVA (30/09/2026) ══════
    //
    // Mesma armadilha que a casa tinha e saiu em 28/09, que ficou esquecida no mundo do afiliado.
    // O Giovane reclamou: "marca 178 no sistema, porem entrou 250". MEDIDO NA FONTE (API do Datacrazy
    // dele): 231 conversas criadas no dia, 185 chegaram ate a gente e 46 NUNCA chegaram - 35 delas
